        done(err);
      }
    });
  });

  it('injects reload script into index page', (done) => {
    writeMarkdown(contentDir, 'post', 'Content', 'title: Post');
    server = serve({ content: contentDir, output: outputDir, port });

    server.on('listening', async () => {
